const art = items[0].json;
const title   = art.title   || '';
const content = art.content || '';
const source  = art.source  || '';
const url     = art.url     || '';
const pubDate = art.published_at || '';

const systemPrompt = `You are an expert FMCG (Fast-Moving Consumer Goods) deal intelligence analyst. 
Your task is to extract structured intelligence from news articles.

Rules:
- Extract ONLY information explicitly stated in the article. No hallucination.
- If deal value is not mentioned, omit it. 
- If geography is unclear, use 'Global' or 'Unknown'.
- If it's not a deal/transaction article, set deal_type to 'none'.
- confidence_score reflects how certain you are about the extraction (0.0–1.0).
- Return ONLY valid JSON — no markdown, no explanation.`;

const userPrompt = `Analyze this FMCG news article and extract structured intelligence.

Source: ${source}
URL: ${url}
Published: ${pubDate}
Title: ${title}
Content: ${content.substring(0, 3000)}

Return exactly this JSON structure:
{
  "headline": "concise 1-line headline under 100 chars",
  "summary": "2-3 sentence factual summary of the key development",
  "category": "Deals | Trends | Product Launch | Regulatory | Other",
  "companies": ["Company A", "Company B"],
  "deal_type": "acquisition | merger | partnership | expansion | divestiture | investment | joint_venture | ipo | none",
  "geography": "country or region (e.g. India, US, Europe, Global)",
  "deal_value": "deal value with currency if mentioned, else null",
  "key_insights": [
    "insight 1 (max 15 words)",
    "insight 2 (max 15 words)",
    "insight 3 (max 15 words)"
  ],
  "confidence_score": 0.0
}`;

return [{
  json: {
    raw_id: art.id,
    raw_url: url,
    raw_source: source,
    raw_published_at: pubDate,
    system_prompt: systemPrompt,
    user_prompt: userPrompt,
  }
}];

const results = [];

for (const item of items) {
  const resp    = item.json;
  const rawId   = item.json.raw_id   || $('Build Claude Prompt').first().json.raw_id;
  const rawUrl  = item.json.raw_url  || $('Build Claude Prompt').first().json.raw_url;
  const source  = item.json.raw_source || $('Build Claude Prompt').first().json.raw_source;
  const pubDate = item.json.raw_published_at || $('Build Claude Prompt').first().json.raw_published_at;

  if (!resp || resp.error) {
    console.warn('Claude API error:', JSON.stringify(resp?.error));
    results.push({ json: { _error: true, raw_id: rawId } });
    continue;
  }

  const textContent = resp.content?.[0]?.text || '';
  let parsed;
  try {
    // Strip any markdown code fences if present
    const cleaned = textContent.replace(/^```json?\s*/m, '').replace(/\s*```$/m, '').trim();
    parsed = JSON.parse(cleaned);
  } catch (e) {
    console.warn('JSON parse error:', e.message, '| Raw:', textContent.substring(0, 200));
    results.push({ json: { _error: true, raw_id: rawId } });
    continue;
  }

  results.push({
    json: {
      raw_id:           rawId,
      headline:         (parsed.headline   || '').substring(0, 255),
      summary:          parsed.summary     || null,
      category:         parsed.category    || 'Other',
      companies:        JSON.stringify(parsed.companies || []),
      deal_type:        parsed.deal_type   || 'none',
      geography:        parsed.geography   || null,
      deal_value:       parsed.deal_value  || null,
      key_insights:     JSON.stringify(parsed.key_insights || []),
      confidence_score: parseFloat(parsed.confidence_score) || 0.5,
      source,
      original_url:     rawUrl,
      article_date:     pubDate,
      published:        false,
      _error:           false,
    }
  });
}

return results;

// Build company_mentions rows from the newly inserted article
const processed = items[0].json;
const articleId = Array.isArray(processed) ? processed[0]?.id : processed.id;
if (!articleId) return [];

const companies = JSON.parse(items[0].json.companies || '[]');
const dealType  = items[0].json.deal_type || 'none';

// Infer role: first company = acquirer/investor, rest = targets (heuristic)
return companies.map((name, idx) => ({
  json: {
    _article_id: articleId,
    company_name: name,
    article_id: articleId,
    mention_type: idx === 0 ? (dealType === 'acquisition' ? 'acquirer' : 'investor') : 'target',
  }
}));
